UPDATE games SET igdb_id = 7444, igdb_url = 'https://www.igdb.com/games/shovel-knight', id = 'shovel-knight-wii-u', title = 'Shovel Knight', image_url = 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobaa7.jpg', summary = 'Shovel Knight is a sweeping classic action adventure game with awesome gameplay, memorable characters, and an 8-bit retro aesthetic. It''s a hot mashup of new and old! You play as the eponymous Shovel Knight, a small knight with a huge quest. Shovel Knight has come to this land with two goals: to defeat the evil Enchantress and quest for his lost beloved. He wields a Shovel Blade: a multipurpose weapon whose techniques have now been lost to the ages. Always honest and helpful, Shovel Knight is a shining example of the code of Shovelry: Slash Mercilessly and Dig Tirelessly!

But, between Shovel Knight and his beloved stands a cadre of villainous knights. These terrible foes, known as The Order of No Quarter, have been dispatched to prevent Shovel Knight from reaching the Enchantress, and will pursue their mission at any cost. If you love games with perfect platforming, beautiful art, infectious music, crazy bosses, humor and levity, and real heart… Shovel Knight is for you!', genres = 'Platform, Adventure, Indie', collections = 'Shovel Knight', franchises = 'Shovel Knight' WHERE stable_id = 1422;
UPDATE game_releases SET release_date = '2015-11-03' WHERE game_id = 1422;
UPDATE games SET igdb_id = 7444, igdb_url = 'https://www.igdb.com/games/shovel-knight', id = 'shovel-knight-nintendo-3ds', title = 'Shovel Knight', image_url = 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobaa7.jpg', summary = 'Shovel Knight is a sweeping classic action adventure game with awesome gameplay, memorable characters, and an 8-bit retro aesthetic. It''s a hot mashup of new and old! You play as the eponymous Shovel Knight, a small knight with a huge quest. Shovel Knight has come to this land with two goals: to defeat the evil Enchantress and quest for his lost beloved. He wields a Shovel Blade: a multipurpose weapon whose techniques have now been lost to the ages. Always honest and helpful, Shovel Knight is a shining example of the code of Shovelry: Slash Mercilessly and Dig Tirelessly!

But, between Shovel Knight and his beloved stands a cadre of villainous knights. These terrible foes, known as The Order of No Quarter, have been dispatched to prevent Shovel Knight from reaching the Enchantress, and will pursue their mission at any cost. If you love games with perfect platforming, beautiful art, infectious music, crazy bosses, humor and levity, and real heart… Shovel Knight is for you!', genres = 'Platform, Adventure, Indie', collections = 'Shovel Knight', franchises = 'Shovel Knight' WHERE stable_id = 1322;
UPDATE game_releases SET release_date = '2015-10-13' WHERE game_id = 1322;
UPDATE games SET igdb_id = 19456, igdb_url = 'https://www.igdb.com/games/ori-and-the-blind-forest-definitive-edition', id = 'ori-and-the-blind-forest-definitive-edition-xbox-one', title = 'Ori and the Blind Forest: Definitive Edition', image_url = 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2s0m.jpg', summary = 'The forest of Nibel is dying. After a powerful storm sets a series of devastating events in motion, Ori must journey to find courage and confront a dark nemesis to save the forest of Nibel. “Ori and the Blind Forest” tells the tale of a young orphan destined for heroics, through a visually stunning Action-Platformer crafted by Moon Studios. Featuring hand-painted artwork, meticulously animated character performance, a fully orchestrated score and dozens of new features in the Definitive Edition, “Ori and the Blind Forest” explores a deeply emotional story about love and sacrifice, and the hope that exists in us all.

NEW IN THE DEFINITIVE EDITION
• Packed with new and additional content: New areas, new secrets, new abilities, more story sequences, multiple difficulty modes, full backtracking support and much more!
• Discover Naru’s past in two brand new environments.
• Master two powerful new abilities – Dash and Light Burst.
• Find new secret areas and explore Nibel faster by teleporting between Spirit Wells.', genres = 'Platform, Adventure', collections = 'Ori' WHERE stable_id = 4199;
UPDATE game_releases SET release_date = '2016-06-14' WHERE game_id = 4199;
UPDATE games SET igdb_id = 77220, igdb_url = 'https://www.igdb.com/games/return-to-castle-wolfenstein-tides-of-war', id = 'return-to-castle-wolfenstein-tides-of-war-xbox', title = 'Return to Castle Wolfenstein: Tides of War', image_url = 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y04.jpg', summary = 'Return to Castle Wolfenstein: Tides of War is an updated re-release for the Xbox based on the original PC version Return to Castle Wolfenstein. Next to the full, original singleplayer campaign, there are 7 new prologue levels that show how B.J. and Agent One first met and how they got captured and imprisoned at Wolfenstein Castle. There is also a secret bonus awarded at the end of every level when every secret area has been found.', genres = 'Shooter', collections = 'Wolfenstein', franchises = 'Wolfenstein' WHERE stable_id = 3711;
UPDATE game_releases SET release_date = '2003-05-06' WHERE game_id = 3711;
UPDATE games SET igdb_id = 23373, igdb_url = 'https://www.igdb.com/games/the-talos-principle-deluxe-edition', id = 'the-talos-principle-deluxe-edition-nintendo-switch', title = 'The Talos Principle: Deluxe Edition', image_url = 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9diw.jpg', summary = 'The Talos Principle is a philosophical first-person puzzle game from Croteam, the creators of the Serious Sam series, and written by Tom Jubert (FTL, The Swapper) and Jonas Kyratzes (Infinite Ocean). Players are tasked with solving a series of increasingly difficult and complex puzzles woven into a metaphysical parable about intelligence and meaning in an inevitably doomed world.

This definitive version contains the original puzzler in all of its glory and the ambitious expansion The Talos Principle: Road to Gehenna.', genres = 'Shooter, Puzzle, Strategy, Adventure, Indie' WHERE stable_id = 1832;
UPDATE games SET igdb_id = 16748, igdb_url = 'https://www.igdb.com/games/super-mario-advance-4-super-mario-bros-3', image_url = 'https://images.igdb.com/igdb/image/upload/t_cover_big/co229t.jpg', summary = 'Super Mario Advance 4 is a GBA remake of Super Mario Bros. 3 for the NES.

Super Mario Advance is a four-part series for the GBA with Super Mario games of the NES and SNES era. The remakes came with adjusted graphics, sound and additional content. Each game of the series includes additionally the arcade-classic "Mario Bros" which can be played in multiplayer via link cable.', genres = 'Platform', collections = 'Super Mario Advance', franchises = 'Mario' WHERE stable_id = 543;
