UPDATE games SET igdb_id = 143442, igdb_url = 'https://www.igdb.com/games/prince-of-persia-arabian-nights', id = 'prince-of-persia-arabian-nights-dreamcast', title = 'Prince of Persia: Arabian Nights', image_url = 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sxo.jpg', summary = 'Prince of Persia: Arabian Nights is the Dreamcast port of Prince of Persia 3D. It was developed by Avalanche Software and published by Mattel Interactive in North America a year after the original was released. There are several notable differences between the two versions, the most immediately noticeable one is the movement of prince being much faster in the port. The port also does not have the quicksave/quickload feature unlike the original, and there some level layouts changes ranging from slight modifications to entire levels being just removed.', genres = 'Adventure', collections = 'Prince of Persia', franchises = 'Prince of Persia' WHERE stable_id = 3557;
